// ---------------------------------------------------------------------------
// --- Replaces indentation with uni.shiftin and uni.shiftout
//     oneIndent, if defined, must be '\t' or some number of space chars
//     there will always be a terminating newline

export const str2indents = (
		str: string
		): string => {

	assert(!str.includes(uni.shiftin), "Bad input string, has shiftin")
	assert(!str.includes(uni.shiftout), "Bad input string, has shiftout")

	resetOneIndent()
	let curLevel = 0
	const lLines = mkArray(allLinesIn(str), function*(line) {
		const [level, str] = splitLine(line)
		if (str === '') {
			yield '\n'
		}
		else {
			const prefix = (
				  (level > curLevel) ? uni.shiftin.repeat(level - curLevel)
				: (level < curLevel) ? uni.shiftout.repeat(curLevel - level)
				: ''
				)
			curLevel = level
			yield `${prefix}${str}\n`
		}
	})

	const block = lLines.join('')
	return (
		  (curLevel === 0)
		? block
		: block + uni.shiftout.repeat(curLevel) + '\n'
		)
}

// ---------------------------------------------------------------------------
// ASYNC

export const parseText = async <T = unknown,>(
		stub: string,
		text: string,
		hOptions: hash = {}
		): AutoPromise<T> => {

	type opt = {
		trace: boolean
		abortOnError: boolean
		}
	const {trace, abortOnError} = getOptions<opt>(hOptions, {
		trace: false,
		abortOnError: true
		})

	let parseMatcher
	try {
		// --- Make sure parser is compiled and up to date
		const heraFileName = `${stub}.parse.hera`
		const heraPath = findFile(heraFileName)
		assert(defined(heraPath), `No such file: ${heraFileName}`)
		const hResult = await procOneFile(heraPath, doCompileHera)
		assert(hResult.success, `parse of ${heraPath} failed`)

		const tsFileName = `${stub}.parse.ts`
		DBG(`tsFileName = ${tsFileName}`)
		const path = findFile(tsFileName)
		assert(defined(path), "No such file: ${tsFileName}")
		assert(isFile(path), `Not a file: ${path}`)

		const fileURL = toFileUrl(path).href
		const {pm, beginParse, parse} = await import(fileURL)
		parseMatcher = pm
		assert(defined(parse), "Parser not found")
		assert(isFunction(parse), "Parser not a function")

		const newText = beginParse(text)
		if (isString(newText)) {
			text = newText
		}

		pm.reset(text)

		// --- I don't know why parse() sometimes returns a function
		//     that must be called to get the actual return value
		let result = parse(text)
		if (isFunction(result)) {
			result = result()
		}

		if (trace) {
			pm.dumpParseInfo()
		}

		// --- Return a deep copy of the result
		return deepCopy(result)
	}

	catch (err) {
		if ((logLevel !== 'silent') && (logLevel !== 'testing')) {
			ERR(getErrStr(err))
			ERR(`Parser: '${stub}'`, 'PARSE ERROR')
			LOG(`Parsing: ${esc(text)}`)
			parseMatcher.dumpParseInfo()
		}
		throw err
	}
}

// ---------------------------------------------------------------------------
// ASYNC

export const parseFile = async <T = unknown,>(
		stub: string,
		path: string,
		hOptions: hash = {}
		): AutoPromise<T> => {

	const file = new CReadableFile(path)
	const hMetaData = await file.metaData()
	const contents = await file.getContents()
	return await parseText<T>(stub, contents, {hMetaData})
}

